python3 << 'EOF'
import json, math
import numpy as np
from PIL import Image

im = Image.open('barcode.png').convert('RGB')
w,h = im.size
bc = np.asarray(im.resize((1,h), Image.BOX), dtype=float).reshape(h,3).mean(axis=0)  # not needed
# column means
cols = np.asarray(im, dtype=float).mean(axis=0)  # (1000,3)

data = json.load(open('frames.json'))
# build per-candidate 1s-resolution color series by averaging frames overlapping each second
series={}
for key,d in data.items():
    dur=d['duration']; interval=d['interval']/1000.0
    n = int(math.ceil(dur))
    arr=np.zeros((n+2,3)); cnt=np.zeros(n+2)+1e-9
    for (t,r,g,b) in d['frames']:
        i0=int(t//1); i1=int((t+interval)//1)
        for i in range(i0,i1+1):
            if i<=n+1:
                ov=min(i+1,t+interval)-max(i,t)
                if ov>0:
                    arr[i]+=[r*ov,g*ov,b*ov]; cnt[i]+=ov
    series[key]={'dur':dur,'colors':arr/cnt.reshape(-1,1)}

def eval_window(key, dur_used, offset):
    # barcode column x -> video time = offset + (x+0.5)/1000 * dur_used
    C=series[key]['colors']; n=len(C)
    xs=np.arange(w)
    ts=offset+(xs+0.5)/w*dur_used
    idx=np.clip(ts.astype(int),0,n)
    pred=C[idx]
    return np.abs(pred-cols).sum(axis=1).mean()

best=[]
for key,d in data.items():
    dur=series[key]['dur']
    bb=(1e9,None,None)
    for scale in [1.0, 0.95, 0.9, 0.85, 0.8, 0.75, 0.7, 0.6, 0.5]:
        dur_used=dur*scale
        for offset in range(0, max(1,int(dur-dur_used))+1, 2):
            m=eval_window(key,dur_used,offset)
            if m<bb[0]: bb=(m,dur_used,offset)
    best.append((bb[0],key,d['name'],dur,bb[1],bb[2]))
best.sort()
for m,key,name,dur,du,off in best:
    print(f"{m:7.2f}  {key} {name:26s} dur={dur}s window={du:.0f}s offset={off}s")
EOF

